# Hook function to patch before test module imports
def pytest_load_initial_conftests(early_config, parser, args):
    # Patch subprocess to mock nvidia-smi
    class MockResult:
        returncode = 0
        stdout = 'mock GPU'
        stderr = ''

    original_run = subprocess.run
    def patched_run(cmd, *args, **kwargs):
        if isinstance(cmd, str):
            cmd_str = cmd
        else:
            cmd_str = ' '.join(cmd) if isinstance(cmd, list) else str(cmd)
        if 'nvidia-smi' in cmd_str:
            return MockResult()
        return original_run(cmd, *args, **kwargs)

    subprocess.run = patched_run
    if not hasattr(subprocess, 'DEVNULL'):
        subprocess.DEVNULL = -3

    # Create mock CUDA module
    class MockDeviceProperties:
        multi_processor_count = 1
        total_memory = int(1e10)
        name = 'Mock GPU'
        major = 8
        minor = 9
        warp_size = 32

    class MockCUDA:
        _is_available = True
        _current_device = 0
        _mocked = True

        @staticmethod
        def is_available():
            return True

        @staticmethod
        def current_device():
            return 0

        @staticmethod
        def device_count():
            return 1

        @staticmethod
        def get_device_properties(device):
            return MockDeviceProperties()

        @staticmethod
        def device(idx):
            return MockDeviceProperties()

    # Patch torch.cuda if torch is already imported
    if 'torch' in sys.modules:
        torch = sys.modules['torch']
        torch.cuda = MockCUDA()

    # Pre-populate sys.modules so future imports get the mock
    sys.modules['torch.cuda'] = MockCUDA()
