if not hasattr(subprocess, 'DEVNULL'):
    subprocess.DEVNULL = -3

# Now we need to ensure torch.cuda is mocked before torch is imported
# Store original import
_original_import = __builtins__.__import__

def _mock_import(name, *args, **kwargs):
    result = _original_import(name, *args, **kwargs)
    if name == 'torch.cuda' and not hasattr(result, '_mocked'):
        class MockDeviceProperties:
            multi_processor_count = 1
            total_memory = int(1e10)
            name = 'Mock GPU'
            major = 8
            minor = 9
            warp_size = 32

        class MockCUDA:
