            _current_device = 0
            _mocked = True

            @staticmethod
            def is_available():
                return True

            @staticmethod
            def current_device():
                return 0

            @staticmethod
            def device_count():
                return 1

            @staticmethod
            def get_device_properties(device):
                return MockDeviceProperties()

            @staticmethod
            def device(idx):
                return MockDeviceProperties()

        # Replace cuda module
        sys.modules['torch.cuda'] = MockCUDA()
    return result

# Apply import hook
__builtins__.__import__ = _mock_import

# Also patch torch.cuda if already imported
if 'torch' in sys.modules and hasattr(sys.modules['torch'], 'cuda'):
    import torch.cuda as cuda_module
    # Already patched via import hook
